import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Spellbooks, Scrolls & Reagents","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/spellbooks-scrolls-and-reagents.md","filePath":"en/guide/magic/spellbooks-scrolls-and-reagents.md"}'),l={name:"en/guide/magic/spellbooks-scrolls-and-reagents.md"};function o(n,e,i,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="spellbooks-scrolls-reagents" tabindex="-1">Spellbooks, Scrolls &amp; Reagents <a class="header-anchor" href="#spellbooks-scrolls-reagents" aria-label="Permalink to &quot;Spellbooks, Scrolls &amp; Reagents&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Learned magical knowledge should survive death.</li><li>Rare books, casting scrolls and reagents remain physical resources with loot risk.</li><li>Scrolls offer temporary tactical access, not automatic permanent learning.</li></ul><p><span id="spellbooks-scrolls-and-reagents"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Personal spellbook</td><td>Represents known magic and should not normally drop; its exact protection and replacement remain open.</td></tr><tr><td>Rare grimoire</td><td>May hold valuable annotations, patterns or reference benefits and can be lootable.</td></tr><tr><td>Casting scroll</td><td>A consumable may provide temporary spell access, a variant or faster reference; eligibility and failure consumption remain open.</td></tr><tr><td>Reagents</td><td>Physical materials may act as catalysts or stabilizers. Recipes and substitutions remain open.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Magery scrolls can be cast or added to a spellbook.</td><td>Ordinary casting scrolls provide temporary access without permanently teaching the pattern.</td></tr><tr><td>Spellbooks collect spells; casting uses magical resources.</td><td>Separate persistent knowledge from valuable physical references and consumables at risk.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/an-introduction-to-spellcasting/" target="_blank" rel="noreferrer">Official UO: spellcasting</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An emergency Dispel scroll could shorten reference time for an unprepared spell at consumable cost. It would not teach Dispel permanently or guarantee a successful cast.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Protecting knowledge is not general equipment insurance. Scrolls and reagents generally drop on death; special teaching artifacts and the boundary between personal books and rare grimoires still need rules.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">Spellbooks, Scrolls &amp; Reagents</a> design specification.</p>',18)])])}const u=a(l,[["render",o]]);export{m as __pageData,u as default};
